# 输入: 对称群 G 的置换列表(每个是位置集 X={0..n-1} 上的置换), 颜色数 m
# 输出: 本质不同染色数

def polya(G, m):
  total = 0
  for g in G:
    c = number_of_cycles(g)   # 分解 g 的轮换个数(含1-轮换)
    total += m ** c
  return total // len(G)       # 或模 p 意义下乘逆元

def number_of_cycles(g):
  seen = [False]*len(g); cnt = 0
  for i in range(len(g)):
    if not seen[i]:
      cnt += 1
      j = i
      while not seen[j]:
        seen[j] = True
        j = g[j]
  return cnt
